  });
  afterEach(() => vi.useRealTimers());

  it('se conecta a la URL y refleja el estado en vivo', () => {
    const { result, ws } = setup();
    expect(ws().url).toBe('ws://test/ws');
    expect(result.current).toBe(false);
    act(() => ws().onopen?.());
    expect(result.current).toBe(true);
    act(() => ws().onclose?.());
    expect(result.current).toBe(false);
  });

